// El primer texto es la solución editorial. La función rota su posición al construir los datos.
let serial = 0;
const q = (prompt, right, wrong1, wrong2, explanation, type='choice') => {
 const shift = serial++ % 3;
 const options = [right,wrong1,wrong2];
 for(let i=0;i<shift;i++) options.push(options.shift());
 return {type,prompt,options,answer:options.indexOf(right),explanation};
};
const tf = (prompt, answer, explanation) => ({type:'boolean',prompt,options:['Verdadero','Falso'],answer:answer?0:1,explanation});
const order = (prompt, items, explanation) => ({type:'order',prompt,items,explanation});
const match = (prompt, pairs, explanation) => ({type:'match',prompt,pairs,explanation});
